// Package cleanup owns extractor scratch artifacts. Workspace cleanup also
// removes Markdown still marked as generated and absent from the Git index.
import { execFileSync } from 'node:child_process'
import { lstatSync, readFileSync, readdirSync, rmSync } from 'node:fs'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'

// Package commands run from the package, but doc models and rendered Markdown are shared.
const workspace = fileURLToPath(new URL('../', import.meta.url))
const workspaceTemp = join(workspace, 'temp')

const documenterMarker =
  '<!-- Do not edit this file. It is automatically generated by API Documenter. -->'
const extractorMarker =
  '> Do not edit this file. It is a report generated by [API Extractor](https://api-extractor.com/).'

// Work on regular scratch files only. A linked temp directory may belong elsewhere.
function removeScratchFiles(directory, matches) {
  if (!lstatSync(directory, { throwIfNoEntry: false })?.isDirectory()) return

  for (const file of readdirSync(directory, { withFileTypes: true })) {
    if (file.isFile() && matches(file.name)) {
      rmSync(join(directory, file.name), { force: true })
    }
  }
}

// The index protects staged as well as committed files. Generator headers
// distinguish abandoned outputs from handwritten Markdown in those directories.
function removeUntrackedGeneratedMarkdown() {
  const candidates = execFileSync(
    'git',
    ['ls-files', '--others', '-z', '--', 'docs/', 'api-reports/'],
    { cwd: workspace, encoding: 'utf8' },
  )
  for (const candidate of candidates.split('\0')) {
    if (!candidate.endsWith('.md')) continue
    const path = join(workspace, candidate)
    if (!lstatSync(path, { throwIfNoEntry: false })?.isFile()) continue

    const contents = readFileSync(path, 'utf8')
    const generated = candidate.startsWith('docs/')
      ? contents.startsWith(documenterMarker)
      : candidate.endsWith('.api.md') &&
        contents.startsWith('## API Report File for ') &&
        contents.includes(extractorMarker)
    if (generated) rmSync(path, { force: true })
  }
}

// A package owns its named outputs. The workspace command also clears obsolete doc models.
const [packageName, reportPolicy] = process.argv.slice(2)
if (packageName) {
  removeScratchFiles(
    workspaceTemp,
    (name) => name === `${packageName}.api.json`,
  )
  // The ESLint plugin keeps its candidate report under version control.
  if (reportPolicy !== '--keep-report') {
    removeScratchFiles('temp', (name) => name === `${packageName}.api.md`)
  }
} else {
  // Root temp reserves this suffix for API Extractor doc models.
  removeScratchFiles(workspaceTemp, (name) => name.endsWith('.api.json'))
  removeUntrackedGeneratedMarkdown()
}
